"use strict";
// Local prototype only. Browser role selection is not secure authentication.
const localDay=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const KEY='kinecto-attendance-system-v3';const AUTH='kinecto-attendance-role-v2';const $=id=>document.getElementById(id);
const people=[['MOCK-0187','Student MOCK-0187','MOCK-TAG-0187',['EPH810S','EPH710S']],['MOCK-0241','Student MOCK-0241','MOCK-TAG-0241',['EPH810S']],['MOCK-0316','Student MOCK-0316','MOCK-TAG-0316',['EPH810S']],['MOCK-0428','Student MOCK-0428','MOCK-TAG-0428',['EPH710S']],['MOCK-0572','Student MOCK-0572','MOCK-TAG-0572',['EPH810S']],['MOCK-0639','Student MOCK-0639','MOCK-TAG-0639',['EPH810S']]].map(([id,name,tag,modules])=>({id,name,tag,modules}));
const initial=()=>({audit:[],rooms:[{name:'E201',building:'Engineering',seats:120},{name:'E105',building:'Engineering',seats:60},{name:'FabLab',building:'Engineering',seats:34}],readers:[{id:'E201-SIM',room:'E201',status:'Online'},{id:'E105-A',room:'E105',status:'Offline'},{id:'FL-01',room:'FabLab',status:'Online'}],sessions:[{id:'EPH810S-LECT-01',module:'EPH810S',title:'Emerging Practices in HCI',type:'Lecture',room:'E201',reader:'E201-SIM',time:'10:00 – 12:00',status:'scheduled',date:localDay(new Date())},{id:'EPH810S-TUT-01',module:'EPH810S',title:'Emerging Practices in HCI',type:'Tutorial',room:'E105',reader:'E105-A',time:'08:00 – 09:50',status:'scheduled',date:localDay(new Date())},{id:'EPH710S-LAB-01',module:'EPH710S',title:'Interaction Design Studio',type:'Lab',room:'FabLab',reader:'FL-01',time:'14:00 – 16:00',status:'scheduled'}],events:[],tapAttempts:[],queries:[],corrections:[],selectedSession:'EPH810S-LECT-01',courses:{EPH810S:'Dr. Mark',EPH710S:'Ms. N. Amutenya'},settings:{late:10,openBefore:5,autoClose:true,alertReader:true,alertAbsence:true,alertSummary:false,alertAutoOpen:false,alertCorrection:true},users:[{name:'Dr. Mark',email:'mark@nust.na',role:'Lecturer',course:'EPH810S'},{name:'Ms. N. Amutenya',email:'amutenya@nust.na',role:'Lecturer',course:'EPH710S'},{name:'John Doe',email:'admin@nust.na',role:'Admin',course:''}]});
function load(){try{let o=JSON.parse(localStorage.getItem(KEY));if(o&&Array.isArray(o.sessions)&&Array.isArray(o.events)&&Array.isArray(o.queries)){o.audit ||= [];o.readers ||= initial().readers;o.corrections ||= [];o.courses ||= initial().courses;o.settings ||= initial().settings;o.users ||= initial().users;o.rooms ||= initial().rooms;o.tapAttempts ||= [];return o}}catch(e){}return initial()};let data=load();let role=sessionStorage.getItem(AUTH)||'';let page='Today';let notice='';let lastRoute='';let navigatingHistory=false;const save=()=>localStorage.setItem(KEY,JSON.stringify(data));const audit=(action,detail)=>{data.audit.push({id:'A-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),action,detail,actor:roles[role]?.name||'Sample user',timestamp:new Date().toISOString()});save()};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const person=id=>people.find(p=>p.id===id);const courseTitle=m=>data.courseTitles?.[m]||data.sessions.find(x=>x.module===m&&x.title)?.title||m;const session=id=>data.sessions.find(s=>s.id===id);const selected=()=>session(data.selectedSession)||data.sessions[0];const clock=t=>new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});const fmt=t=>new Date(t).toLocaleString();const pill=(label,kind)=>`<span class="pill ${kind||''}">${esc(label)}</span>`;
const roles={lecturer:{name:'Dr. Mark',detail:'Lecturer · EPH810S',nav:['Today','Sessions','Register','Reports','Messages','Settings']},admin:{name:'John Doe',detail:'NUST admin · ICT',nav:['Overview','Readers','Rooms','Courses','Reports','Roles','Audit log','Settings']},student:{name:'Student MOCK-0187',detail:'Student · MOCK-0187',nav:['Tap Station','My Attendance','My Modules','Messages','Settings']}};
function login(){ $('app').innerHTML=`<div class="login-wrap"><form class="login-card" id="loginForm"><div class="login-brand"><img class="brand-logo" src="assets/kinecto-attendance-logo.png" alt="Kinecto Attendance logo"><h1>Attendance Desk</h1><p>Kinecto Attendance System for lecturers, students and NUST administrators</p></div><div class="field"><label for="role">Choose your sample account</label><select id="role"><option value="lecturer">Lecturer · Dr. Mark</option><option value="student">Student · MOCK-0187</option><option value="admin">NUST administrator · John Doe</option></select></div><button class="btn primary full" type="submit">Sign in</button></form></div>`;$('loginForm').onsubmit=e=>{e.preventDefault();role=$('role').value;sessionStorage.setItem(AUTH,role);page=roles[role].nav[0];history.pushState({role,page},'', '#'+role+'/'+encodeURIComponent(page));lastRoute=role+'/'+page;render()}}
function shell(body){let user=roles[role];let nav=user.nav.map(n=>`<button data-page="${esc(n)}" class="${n===page?'active':''}"><span class="nav-dot"></span>${esc(n)}</button>`).join('');$('app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="assets/kinecto-attendance-logo.png" alt="Kinecto Attendance logo"><span><strong>Kinecto Attendance</strong><small>${role==='admin'?'Attendance admin':'Attendance desk'}</small></span></div><nav class="nav" aria-label="Main navigation">${nav}</nav><div class="sidebar-bottom"><div class="profile"><span class="avatar">${role==='lecturer'?'DM':role==='admin'?'PS':'S1'}</span><div><strong>${esc(user.name)}</strong><small>${esc(user.detail)}</small></div></div><button class="logout-link" id="logout">Log out</button></div></aside><div class="main"><main class="content">${notice?`<div class="notice">${esc(notice)}</div>`:''}${body}</main></div></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;notice='';render()});$('logout').onclick=()=>{sessionStorage.removeItem(AUTH);role='';notice='';history.pushState({role:'',page:''},'',location.pathname+location.search);lastRoute='';login()}}
function heading(title,subtitle,action=''){return `<div class="heading"><div><h1>${esc(title)}</h1><p class="sub">${esc(subtitle)}</p></div>${action}</div>`}
function sessPicker(){return `<div class="field"><label for="sessionSelect">Selected session</label><select id="sessionSelect">${data.sessions.map(s=>`<option value="${s.id}" ${s.id===data.selectedSession?'selected':''}>${esc(s.module)} · ${esc(s.type)} · ${esc(s.room)} · ${esc(s.time)}</option>`).join('')}</select></div>`}
function eventsFor(id){return data.events.filter(e=>e.sessionId===id)}function attendanceFor(id){let s=session(id);let registered=people.filter(p=>p.modules.includes(s.module));let ev=eventsFor(id);let ins=new Set(ev.filter(e=>e.direction==='IN').map(e=>e.tagId));let outs=new Set(ev.filter(e=>e.direction==='OUT').map(e=>e.tagId));let corrected=new Set(data.corrections.filter(c=>c.sessionId===id).map(c=>c.tagId));return {registered,ev,ins,outs,corrected,present:new Set([...ins,...corrected])}}
function statusOf(tag,id){let a=attendanceFor(id);if(a.corrected.has(tag))return 'Fixed by hand';if(!a.ins.has(tag))return 'Absent';if(a.outs.has(tag))return 'Checked out';return 'Present'}
function setSession(){let x=$('sessionSelect');if(x)x.onchange=()=>{data.selectedSession=x.value;save();render()}}
function today(){let s=selected(),a=attendanceFor(s.id),n=a.registered.length,live=s.status==='open',progress=n?Math.round(a.present.size/n*100):0;return heading('Today',new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),`<div class="header-actions"><button class="btn outline" data-go="Sessions">View timetable</button><button class="btn primary" id="toggleSession">${live?'Close session':'Open session'}</button></div>`)+`<div class="today-grid"><section class="panel live-card"><div class="live-label">${live?'LIVE SESSION':'SESSION '+esc(s.status.toUpperCase())}</div><h2>${esc(s.module)} · ${esc(s.title)}</h2><p class="muted">${esc(s.type)} · ${esc(s.room)} · ${esc(s.time)} · ${s.openedAt?'Opened '+clock(s.openedAt):s.closedAt?'Closed '+clock(s.closedAt):'Not opened'}</p><div class="stat-big">${a.present.size}<small> / ${n} checked in</small></div><div class="progress"><span style="width:${progress}%"></span></div><div class="metric-row"><div class="metric green">Present<strong>${a.present.size}</strong></div><div class="metric yellow">Tap OUT<strong>${a.outs.size}</strong></div><div class="metric pink">Absent / not yet<strong>${n-a.present.size}</strong></div><div class="metric purple">Fixed by hand<strong>${a.corrected.size}</strong></div></div><div class="actions"><button class="btn dark" id="toggleSessionSecondary">${live?'Close session':'Open session'}</button><button class="btn outline" id="exportSettings">Export attendance CSV</button><button class="btn outline" id="export">Export CSV</button></div></section><section class="panel live-feed"><div class="panel-head"><h3>Live taps</h3><span class="muted">Newest first</span></div>${a.ev.length?a.ev.slice().reverse().slice(0,8).map(e=>`<div class="tap-line"><span class="muted">${clock(e.timestamp)}</span><div><strong>${esc(person(e.tagId)?.name||e.tagId)}</strong><small>${esc(e.tagId)}</small></div>${pill(e.direction==='IN'?'Tap IN':'Tap OUT',e.direction==='IN'?'present':'pending')}</div>`).join(''):'<div class="empty">No taps recorded yet.</div>'}</section></div>${s.status==='closed'?closedSummary(s):''}<section class="panel timeline-panel"><div class="panel-head"><h3>Check-ins over time</h3><span class="muted">Late after ${data.settings.late} minutes</span></div>${checkinChart(s)}</section><section class="panel sessions-panel"><h3>Today’s sessions</h3>${sessionTable()}</section>`}

function sessionTable(){return `<div class="table-scroll"><table><thead><tr><th>Time</th><th>Course</th><th>Type</th><th>Room · reader</th><th>Checked in</th><th>Status</th><th></th></tr></thead><tbody>${data.sessions.map(s=>{let a=attendanceFor(s.id);return `<tr class="${s.id===data.selectedSession?'selected-row':''}"><td><strong>${esc(s.time.split(' ')[0])}</strong></td><td><strong>${esc(s.module)}</strong> ${esc(s.title)}</td><td>${esc(s.type)}</td><td>${esc(s.room)} · ${esc(s.reader)}</td><td><strong>${a.present.size} / ${a.registered.length}</strong></td><td>${pill(s.status==='open'?'Live':s.status,s.status==='open'?'present':'closed')}</td><td><button class="btn outline small" data-select-session="${s.id}">${s.status==='open'?'Open live':'View register'}</button></td></tr>`}).join('')}</tbody></table></div>`}
let weekOffset=0;
function sessions(){let now=new Date(),monday=new Date(now.getFullYear(),now.getMonth(),now.getDate());monday.setDate(monday.getDate()-((monday.getDay()+6)%7)+weekOffset*7);let days=Array.from({length:5},(_,i)=>{let d=new Date(monday);d.setDate(monday.getDate()+i);return d});let slots=['08:00','10:00','12:00','14:00','16:00'];return heading('Sessions',`Week of ${monday.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})} · ${data.sessions.filter(x=>days.some(d=>x.date===localDay(d))).length} sessions`,`<div class="header-actions"><button class="btn outline" id="prevWeek">‹ Prev week</button><button class="btn outline" id="nextWeek">Next week ›</button><button class="btn primary" id="newSession">+ New session</button></div>`)+`<section class="panel"><div class="calendar-wrap"><div class="calendar-grid"><div></div>${days.map(d=>`<strong class="calendar-head">${d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric'})}</strong>`).join('')}${slots.map((t,idx)=>`<span class="calendar-time">${t}</span>${days.map(d=>{let matches=data.sessions.filter(x=>x.date===localDay(d)&&Number(x.time.slice(0,2))>=Number(t.slice(0,2))&&Number(x.time.slice(0,2))<Number(t.slice(0,2))+2);return `<div class="calendar-cell">${matches.map(x=>`<button class="calendar-event ${x.status}" data-select-session="${esc(x.id)}"><strong>${esc(x.module)} ${esc(x.type)}</strong><small>${esc(x.time)} · ${esc(x.room)} · ${attendanceFor(x.id).present.size}/${attendanceFor(x.id).registered.length}</small><span>${esc(x.status==='open'?'Live':x.status==='closed'?'Closed':'Planned')}</span></button>`).join('')}</div>`}).join('')}`).join('')}</div></div></section><div id="sessionModal" class="modal-overlay" hidden></div>`}

function register(){let s=selected(),a=attendanceFor(s.id),tabs=[['all','All',a.registered.length,'navy'],['Present','Present',a.ins.size,'green'],['Checked out','Tap OUT',a.outs.size,'yellow'],['Absent','Absent',a.registered.length-a.present.size,'pink'],['Fixed by hand','Fixed by hand',a.corrected.size,'purple']];return heading('Register',`${s.module} · ${s.type} · ${s.time} · ${s.room}`,`<div class="header-actions"><button class="btn outline" id="export">Export CSV</button><button class="btn primary" id="manualOpen">Mark present by hand</button></div>`)+`<div class="filter-pills">${tabs.map(([v,t,n,c],i)=>`<button class="filter-pill ${c} ${i===0?'chosen':''}" data-register-filter="${v}">${t} ${n}</button>`).join('')}</div><div class="register-grid"><section class="panel register-table">${sessPicker()}<div class="toolbar"><input class="search" id="studentSearch" placeholder="Search name or student number"><select class="search" id="filter"><option value="all">All statuses</option><option value="Present">Present</option><option value="Checked out">Tap OUT</option><option value="Absent">Absent</option><option value="Fixed by hand">Fixed by hand</option></select></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Student no.</th><th>Tap in</th><th>Tap out</th><th>Status</th><th></th></tr></thead><tbody id="registerRows"></tbody></table></div><h3 style="margin-top:24px">Tap history</h3>${eventTable(a.ev.slice().reverse())}<h3 style="margin-top:22px">Manual correction history</h3>${correctionHistory(s.id)}</section><div class="register-side"><section class="panel"><h3>Students below the 75% rule</h3><p class="muted">Attendance is calculated from closed sessions in this course.</p>${riskPanel(s.module)}</section><div id="correctionPanel"><section class="panel"><h3>Mark present by hand</h3><p class="muted">Select a student using Review or the button above. Each correction requires a reason and is recorded in the audit log.</p></section></div></div></div>`}
function registerRows(){let s=selected(),a=attendanceFor(s.id),q=($('studentSearch')?.value||'').toLowerCase(),filter=$('filter')?.value||'all';$('registerRows').innerHTML=a.registered.filter(p=>(p.name.toLowerCase().includes(q)||p.id.toLowerCase().includes(q))&&(filter==='all'||statusOf(p.id,s.id)===filter)).map(p=>{let ev=a.ev.filter(e=>e.tagId===p.id),inEv=ev.find(e=>e.direction==='IN'),outEv=ev.find(e=>e.direction==='OUT'),st=statusOf(p.id,s.id);return `<tr><td><span class="student-cell"><span class="student-avatar">${esc(p.id.slice(-2))}</span><strong>${esc(p.name)}</strong></span></td><td class="tag">${esc(p.id)}</td><td>${inEv?clock(inEv.timestamp):'—'}</td><td>${outEv?clock(outEv.timestamp):'—'}</td><td>${pill(st,st==='Absent'?'absent':st==='Fixed by hand'?'purple':'present')}</td><td><button class="btn outline small" data-correct="${p.id}">Mark by hand</button> <button class="btn outline small" data-student="${p.id}">History</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No matching students.</td></tr>';document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>correctionForm(b.dataset.correct));document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>studentDetail(b.dataset.student))}
function correctionHistory(sid){let rows=data.corrections.filter(c=>c.sessionId===sid).slice().reverse();return rows.length?`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Time</th><th>Reason</th><th>Changed by</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(person(c.tagId)?.name||c.tagId)}</td><td>${fmt(c.timestamp)}</td><td>${esc(c.reason)} ${esc(c.note||'')}</td><td>${esc(c.actor)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No manual corrections recorded.</p>'}
function correctionForm(id){let p=person(id);$('correctionPanel').innerHTML=`<section class="panel"><h2>Mark present by hand</h2><p class="muted">${esc(p.name)} · ${esc(id)} · ${esc(selected().module)}</p><form id="correctionForm"><div class="field"><label for="reason">Reason</label><select id="reason" required><option value="">Choose a reason</option><option>Cuff tag unreadable</option><option>Reader offline</option><option>Forgot the jacket</option><option>Other</option></select></div><div class="field"><label for="correctionNote">Note (optional)</label><textarea id="correctionNote" rows="3"></textarea></div><div class="actions"><button class="btn primary" type="submit">Save correction</button><button class="btn" type="button" id="cancelCorrection">Cancel</button></div></form></section>`;$('cancelCorrection').onclick=()=>{$('correctionPanel').innerHTML=''};$('correctionForm').onsubmit=e=>{e.preventDefault();if(!selected()||!$('reason').value)return;data.corrections.push({tagId:id,sessionId:selected().id,reason:$('reason').value,note:$('correctionNote').value,actor:'Dr. Mark',timestamp:new Date().toISOString()});audit('Manual attendance correction',p.id+' · '+selected().id+' · '+$('reason').value);notice='Manual correction saved with a reason and lecturer name.';render()}}
function tap(){let p=person('MOCK-0187'),mine=data.sessions.filter(x=>p.modules.includes(x.module)),s=mine.find(x=>x.id===data.selectedSession)||mine[0];if(!s)return heading('Tap Station','No registered sessions available');let attempts=(data.tapAttempts||[]).filter(x=>x.studentId===p.id).slice().reverse(),ev=data.events.filter(x=>x.tagId===p.id);return heading('Tap Station','Cuff check-in and check-out')+`<div class="student-tap-grid"><section class="panel reader-panel"><div class="panel-head"><h2>Classroom NFC reader</h2>${pill(s.status==='open'?'Session open':s.status==='closed'?'Session closed':'Scheduled',s.status==='open'?'present':'pending')}</div><div class="minimal-reader"><div class="minimal-reader-box"><div class="reader-top"><span class="reader-light"></span><strong>${esc(s.reader)}</strong></div><div class="reader-target">◎</div><span>Present cuff here</span></div><div class="minimal-reader-meta"><strong>${esc(s.room)}</strong><span>${esc(s.module)} · ${esc(s.type)}</span><span>Tag: ${esc(p.tag)}</span></div></div><p class="muted">The cuff is read only when it is intentionally presented to the reader.</p></section><section class="panel tap-test-panel"><h2>Test a cuff tap</h2><form id="tapForm"><div class="field"><label for="sessionSelect">My session</label><select id="sessionSelect">${mine.map(x=>`<option value="${esc(x.id)}" ${x.id===s.id?'selected':''}>${esc(x.module)} · ${esc(x.type)} · ${esc(x.date||'')} · ${esc(x.status)}</option>`).join('')}</select></div><div class="field"><label>Registered student</label><div class="locked-identity">${esc(p.name)} <small>${esc(p.id)} · ${esc(p.tag)}</small></div></div><div class="field"><label for="direction">Tap direction</label><select id="direction"><option value="IN">Tap IN</option><option value="OUT">Tap OUT</option></select></div><button class="btn primary full" type="submit">Simulate cuff tap</button></form><div id="tapResult" class="tap-feedback" aria-live="polite">${attempts.length?`${esc(attempts[0].result)} · ${fmt(attempts[0].timestamp)}`:'Waiting for first tap.'}</div></section></div><section class="panel student-history"><div class="panel-head"><h2>Tap station activity</h2><span class="muted">${attempts.length} attempts</span></div>${attempts.length?`<div class="table-scroll"><table><thead><tr><th>Time</th><th>Session</th><th>Direction</th><th>Result</th></tr></thead><tbody>${attempts.map(x=>`<tr><td>${fmt(x.timestamp)}</td><td>${esc(session(x.sessionId)?.module||x.sessionId)}</td><td>${esc(x.direction)}</td><td>${pill(x.result,x.accepted?'present':'absent')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No tap attempts yet.</p>'}<h3 style="margin-top:22px">Accepted NFC tap history</h3>${eventTable(ev.slice().reverse())}</section>`}
function record(tagId,direction,source='browser',sessionId=data.selectedSession){let s=session(sessionId),p=person(tagId);if(!s)return 'Session not found.';if(!p)return 'Unknown sample tag.';if(!p.modules.includes(s.module))return 'This student is not registered for the selected module.';if(s.status!=='open'){if(s.status==='closed'&&data.settings.afterClose==='review'){data.lateTapReviews ||= [];data.lateTapReviews.push({tagId,direction,sessionId:s.id,timestamp:new Date().toISOString()});audit('Tap after close flagged for review',tagId+' · '+direction+' · '+s.id);return 'Tap received after session close and flagged for lecturer review. Attendance was not changed.'}return 'This session is not open. Tap rejected. No attendance recorded.';}let ev=eventsFor(s.id).filter(e=>e.tagId===tagId),last=ev.at(-1);if(last&&last.direction===direction&&Date.now()-new Date(last.timestamp).getTime()<10000)return 'Duplicate tap ignored. Wait 10 seconds.';if(direction==='IN'&&ev.some(e=>e.direction==='IN'))return 'Tap IN already recorded for this session.';if(direction==='OUT'&&!ev.some(e=>e.direction==='IN'))return 'Tap OUT rejected. No earlier Tap IN exists.';if(direction==='OUT'&&ev.some(e=>e.direction==='OUT'))return 'Tap OUT already recorded.';data.events.push({tagId,direction,sessionId:s.id,readerId:s.reader,source,timestamp:new Date().toISOString()});audit('NFC tap',tagId+' · '+direction+' · '+s.id);return `${p.name}: Tap ${direction} recorded for ${s.module}.`}
function eventTable(ev){return ev.length?`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Direction</th><th>Time</th><th>Source</th></tr></thead><tbody>${ev.map(e=>`<tr><td>${esc(person(e.tagId)?.name||e.tagId)}</td><td>${pill(e.direction,e.direction.toLowerCase())}</td><td>${fmt(e.timestamp)}</td><td>${esc(e.source)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No events yet.</p>'}
function reports(){let course=reportModule,ss=data.sessions.filter(x=>x.module===course&&x.status==='closed'),rates=ss.map(x=>{let a=attendanceFor(x.id);return a.registered.length?Math.round(a.present.size*100/a.registered.length):0}),avg=rates.length?Math.round(rates.reduce((a,b)=>a+b,0)/rates.length):0,students=people.filter(p=>p.modules.includes(course)).map(p=>({p,rate:ss.length?Math.round(ss.filter(x=>attendanceFor(x.id).present.has(p.id)).length*100/ss.length):0})),low=students.filter(x=>x.rate<75),card=(l,v,c)=>`<div class="metric ${c}">${l}<strong>${v}</strong></div>`,totalTaps=data.events.filter(e=>ss.some(x=>x.id===e.sessionId)),ins=totalTaps.filter(e=>e.direction==='IN').length,outs=totalTaps.filter(e=>e.direction==='OUT').length,manual=data.corrections.filter(c=>ss.some(x=>x.id===c.sessionId)).length;return heading('Reports',`${course} · ${esc(courseTitle(course))} · ${ss.length} completed sessions`,`<div class="header-actions"><select id="reportModule" class="report-select">${Object.keys(data.courses).map(m=>`<option ${m===course?'selected':''}>${m}</option>`).join('')}</select><button class="btn primary" id="exportReport">Export CSV</button></div>`)+`<div class="report-metrics">${card('Average attendance',avg+'%','green')}${card('Sessions held',ss.length,'blue')}${card('Students below 75%',low.length,'pink')}${card('Fixed by hand',manual,'purple')}</div><div class="reports-grid"><section class="panel report-chart"><h3>Attendance per session</h3><div class="chart"><div class="target-line"></div>${rates.map((v,i)=>`<div class="chart-col"><span>${v}%</span><div class="chart-bar ${v<75?'gold':''}" style="height:${Math.max(v,2)}%"></div><small>S${i+1}</small></div>`).join('')||'<p class="empty">No completed sessions yet. Close a session to start the report.</p>'}</div><p class="muted">Target 75%. Calculated from recorded attendance.</p></section><section class="panel"><h3>Students below 75%</h3>${low.map(x=>`<div class="risk-row"><strong>${esc(x.p.name)}</strong><b>${x.rate}%</b><button class="btn outline small" data-remind="${x.p.id}">Send reminder</button></div>`).join('')||'<p>No students below 75% in completed sessions.</p>'}</section></div><section class="panel tap-quality"><h3>Tap quality</h3><div class="report-metrics">${card('Tap IN',ins,'blue')}${card('Tap OUT',outs,'green')}${card('Manual corrections',manual,'purple')}${card('Recorded taps',totalTaps.length,'yellow')}</div><p class="muted">These figures help the jacket team evaluate whether simulated taps are recorded and whether manual corrections are needed.</p></section>`}

function messages(){let list=data.queries.filter(q=>role==='student'?q.studentId==='MOCK-0187':true);return heading('Messages',role==='student'?'Ask your lecturer to review an attendance record':'Review attendance questions from students')+(role==='student'?`<section class="panel"><h2>Report an attendance issue</h2><form id="queryForm"><div class="field"><label for="querySession">Session</label><select id="querySession">${data.sessions.filter(s=>person('MOCK-0187').modules.includes(s.module)).map(s=>`<option value="${s.id}">${esc(s.module)} · ${esc(s.type)}</option>`).join('')}</select></div><div class="field"><label for="queryText">Message to Dr. Mark</label><textarea id="queryText" required rows="4" placeholder="Explain what seems incorrect"></textarea></div><button class="btn primary" type="submit">Send message</button></form></section>`:'')+`<section class="panel"><h2>${role==='student'?'My messages':'Attendance queries'}</h2>${list.length?list.slice().reverse().map(q=>`<div class="message"><div class="panel-head"><strong>${esc(person(q.studentId)?.name)}</strong>${pill(q.status,q.status==='Pending'?'pending':'present')}</div><div class="muted">${esc(session(q.sessionId)?.module)} · ${fmt(q.timestamp)}</div><p>${esc(q.text)}</p>${q.reply?`<p><strong>Lecturer reply:</strong> ${esc(q.reply)}</p>`:''}${role==='lecturer'?`<button class="btn small" data-reply="${q.id}">Review and reply</button>`:''}</div>`).join(''):'<p class="muted">No messages yet.</p>'}</section><div id="replyArea"></div>`}
function replyForm(id){let q=data.queries.find(q=>q.id===id);$('replyArea').innerHTML=`<section class="panel"><h2>Reply to attendance query</h2><form id="replyForm"><div class="field"><label for="reply">Reply</label><textarea id="reply" required rows="3"></textarea></div><button class="btn primary">Send reply</button></form></section>`;$('replyForm').onsubmit=e=>{e.preventDefault();q.reply=$('reply').value;q.status='Reviewed';audit('Attendance query reply',q.id);notice='Reply saved. Attendance was not changed.';render()}}
function studentAttendance(){let p=person('MOCK-0187');return heading('My Attendance','View your own attendance records')+`<div class="note">Your attendance records are read-only. If something is incorrect, send a message to your lecturer.</div><section class="panel"><h2>My sessions</h2><div class="table-scroll"><table><thead><tr><th>Module</th><th>Session</th><th>Status</th><th>Tap IN</th><th>Tap OUT</th></tr></thead><tbody>${data.sessions.filter(s=>p.modules.includes(s.module)).map(s=>{let ev=eventsFor(s.id).filter(e=>e.tagId===p.id);return `<tr><td>${esc(s.module)}</td><td>${esc(s.type)}</td><td>${pill(statusOf(p.id,s.id))}</td><td>${ev.find(e=>e.direction==='IN')?clock(ev.find(e=>e.direction==='IN').timestamp):'—'}</td><td>${ev.find(e=>e.direction==='OUT')?clock(ev.find(e=>e.direction==='OUT').timestamp):'—'}</td></tr>`}).join('')}</tbody></table></div></section><button class="btn primary" data-go="Messages">Report an issue</button>`}
function admin(){let day=localDay(new Date()),tapsToday=data.events.filter(e=>localDay(new Date(e.timestamp))===day).length,readers=data.readers.map(r=>{let room=data.rooms.find(x=>x.name===r.room),last=data.events.filter(e=>e.readerId===r.id).map(e=>e.timestamp).sort().at(-1);return [r.id,room?room.name+' · '+room.building:(r.room||'—'),r.status||'Offline',last?(localDay(new Date(last))===day?clock(last):new Date(last).toLocaleDateString('en-GB',{day:'numeric',month:'short'})):'No taps yet',r.firmware||'Not reported']}).map(r=>r.map(esc)),online=readers.filter(r=>r[2]==='Online').length;let card=(l,v,c)=>`<div class="metric ${c}">${l}<strong>${v}</strong></div>`;return heading('Readers & rooms',readers.length+' cuff readers · '+online+' online',`<button class="btn primary" id="addReader">Add reader</button>`)+`<div class="report-metrics">${card('Online',online,'green')}${card('Offline',readers.length-online,'pink')}${card('Taps today',tapsToday,'blue')}${card('Sessions live now',data.sessions.filter(x=>x.status==='open').length,'yellow')}</div><div class="admin-grid"><section class="panel"><div class="table-scroll"><table><thead><tr><th>Reader</th><th>Room</th><th>Status</th><th>Last tap</th><th>Firmware</th><th></th></tr></thead><tbody>${readers.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${pill(r[2],r[2]==='Online'?'present':'absent')}</td><td>${r[3]}</td><td>${r[4]}</td><td><button class="btn outline small" data-reader-action="${r[0]}">${r[2]==='Online'?'Details':'Notify ICT'}</button></td></tr>`).join('')}</tbody></table></div></section><div class="admin-side"><section class="panel"><h3>Roles</h3><div class="role-card blue"><strong>Lecturer</strong><small>Own courses: open sessions, register, reports</small></div><div class="role-card yellow"><strong>Admin</strong><small>All readers, rooms, courses and reports</small></div><div class="role-card green"><strong>Student / staff wearer</strong><small>Sees own attendance records only</small></div></section><section class="panel privacy-dark"><h3>Privacy rules</h3><p>Stored per tap: session ID, time, tag ID</p><p>Never stored: continuous location, movement, temperature</p><p>Tag ID is matched to a student identifier on the server</p><p>Retention and authentication require NUST approval before deployment</p></section></div></div><p class="sample-note">Last tap and tap counts come from the shared register. Reader status is set by an admin; live hardware monitoring is not connected.</p>`}

let adminPeriod='Semester',adminAuditFilter='All',adminReaderId='',adminWeekFrom='',adminWeekTo='';
function adminReportData(){let closed=data.sessions.filter(x=>x.status==='closed'),filtered=closed.filter(x=>{if(adminPeriod==='Semester')return true;let d=x.date||localDay(new Date());if(adminPeriod==='This week'){let now=new Date(),start=new Date(now);start.setDate(now.getDate()-((now.getDay()+6)%7));return d>=localDay(start)&&d<=localDay(now)}return (!adminWeekFrom||d>=adminWeekFrom)&&(!adminWeekTo||d<=adminWeekTo)});return filtered}
function adminReports(){let ss=adminReportData(),den=ss.reduce((v,x)=>v+attendanceFor(x.id).registered.length,0),num=ss.reduce((v,x)=>v+attendanceFor(x.id).present.size,0),pct=den?Math.round(num/den*100):0,mods=Object.keys(data.courses),rates=mods.map(m=>{let a=ss.filter(x=>x.module===m),d=a.reduce((n,x)=>n+attendanceFor(x.id).registered.length,0),v=a.reduce((n,x)=>n+attendanceFor(x.id).present.size,0);return {m,rate:d?Math.round(v/d*100):null,count:a.length}}),low=rates.filter(x=>x.rate!==null).sort((a,b)=>a.rate-b.rate).slice(0,5),atRisk=people.filter(p=>{let a=ss.filter(x=>p.modules.includes(x.module));return a.length&&a.filter(x=>attendanceFor(x.id).present.has(p.id)).length/a.length<.75}).length,weekly=Array.from({length:10},(_,i)=>{let a=ss.filter(x=>{let d=new Date((x.date||localDay(new Date()))+'T12:00:00'),start=new Date(new Date().getFullYear(),0,1),w=Math.ceil((((d-start)/86400000)+start.getDay()+1)/7);return (w%10)===i});let d=a.reduce((n,x)=>n+attendanceFor(x.id).registered.length,0),v=a.reduce((n,x)=>n+attendanceFor(x.id).present.size,0);return {i:i+1,rate:d?Math.round(v/d*100):null,count:a.length}}),times=['08:00','10:00','12:00','14:00','16:00'],days=['Mon','Tue','Wed','Thu','Fri'],heat=days.map((day,di)=>times.map(t=>ss.filter(x=>{let d=new Date((x.date||localDay(new Date()))+'T12:00:00');return d.getDay()===(di+1)&&x.time.startsWith(t)}).length));return heading('Campus reports',`${adminPeriod} · ${ss.length} completed sessions · shared register`,`<div class="header-actions"><button class="btn outline" id="adminExportCsv">Export CSV</button><button class="btn primary" id="adminExportPdf">Export PDF</button></div>`)+`<div class="filter-pills">${['This week','Semester','Custom'].map(t=>`<button class="btn ${adminPeriod===t?'dark':'outline'} small" data-admin-period="${t}">${t}</button>`).join('')}</div>${adminPeriod==='Custom'?`<div class="actions" style="margin-bottom:16px"><label>From <input type="date" id="adminFrom" value="${adminWeekFrom}"></label><label>To <input type="date" id="adminTo" value="${adminWeekTo}"></label><button class="btn outline" id="applyAdminDates">Apply dates</button></div>`:''}<div class="report-metrics"><div class="metric green">Campus attendance<strong>${pct}%</strong></div><div class="metric pink">Students below 75%<strong>${atRisk}</strong></div><div class="metric blue">Taps read first time<strong>${data.events.length? '100%':'—'}</strong></div><div class="metric purple">Marked by hand<strong>${data.corrections.length}</strong></div></div><section class="panel admin-week-panel"><div class="panel-head"><h3>Attendance per week, campus</h3><strong style="color:#e33">Target 75%</strong></div><div class="admin-bars"><div class="admin-target"></div>${weekly.map(w=>`<button class="admin-bar-cell" data-week-info="${w.i}" title="Week ${w.i}: ${w.count} sessions"><strong>${w.rate===null?'—':w.rate+'%'}</strong><span class="admin-bar ${w.rate!==null&&w.rate<75?'gold':''}" style="height:${w.rate===null?3:w.rate}%"></span><small>W${w.i}</small></button>`).join('')}</div><p class="muted" id="adminChartInfo">Select a bar to inspect its completed-session count. Empty weeks have no recorded data.</p></section><div class="admin-report-bottom"><section class="panel"><h3>Lowest courses</h3>${low.map(x=>`<button class="admin-course-bar" data-low-course="${esc(x.m)}"><strong>${esc(x.m)}</strong><span class="progress"><span style="width:${x.rate}%"></span></span><b>${x.rate}%</b></button>`).join('')||'<p class="muted">No completed sessions in this period.</p>'}<p class="muted" id="adminCourseInfo">Select a course for its recorded attendance.</p></section><section class="panel"><h3>Busiest times</h3><p class="muted">Teaching sessions by weekday and start time. Select a cell to see the count.</p><div class="heatmap"><span></span>${times.map(t=>`<small>${t}</small>`).join('')}${days.map((day,di)=>`<strong>${day}</strong>${heat[di].map((v,ti)=>`<button class="heat-cell" data-heat="${di}-${ti}" style="--heat:${v?Math.min(.2+v*.2,1):.08}" title="${day} ${times[ti]}: ${v} sessions">${v||''}</button>`).join('')}`).join('')}</div><p class="muted" id="adminHeatInfo">Room-planning activity is based on recorded sessions, not a live timetable.</p></section></div>`}

function adminOverview(){let open=data.sessions.filter(x=>x.status==='open'),n=data.events.length,closed=data.sessions.filter(x=>x.status==='closed'),den=closed.reduce((v,x)=>v+attendanceFor(x.id).registered.length,0),num=closed.reduce((v,x)=>v+attendanceFor(x.id).present.size,0),pct=den?Math.round(num/den*100):0;return heading('Campus overview',new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · Semester 2',`<button class="btn primary" id="exportWeek">Export week</button>`)+`<div class="report-metrics"><div class="metric blue">Sessions today<strong>${data.sessions.filter(x=>(x.date||localDay(new Date()))===localDay(new Date())).length}</strong></div><div class="metric green">Live right now<strong>${open.length}</strong></div><div class="metric yellow">Taps today<strong>${data.events.filter(e=>localDay(new Date(e.timestamp))===localDay(new Date())).length}</strong></div><div class="metric pink">Readers offline<strong>${data.readers.filter(x=>x.status==='Offline').length}</strong></div><div class="metric purple">Campus attendance<strong>${pct}%</strong></div></div><div class="admin-grid"><section class="panel"><h3>Attendance by course this week</h3>${Object.keys(data.courses).map(m=>{let ss=closed.filter(x=>x.module===m),total=ss.reduce((v,x)=>v+attendanceFor(x.id).registered.length,0),pres=ss.reduce((v,x)=>v+attendanceFor(x.id).present.size,0),rate=total?Math.round(pres/total*100):0;return `<div class="rowline"><strong>${esc(m)}</strong><div class="progress" style="width:60%"><span style="width:${rate}%"></span></div><strong>${rate}%</strong></div>`}).join('')}</section><section class="panel"><h3>Needs attention</h3>${data.readers.filter(x=>x.status==='Offline').map(x=>`<div class="rowline"><span>${esc(x.id)} offline</span><button class="btn outline small" data-go="Readers">View</button></div>`).join('')||'<p>No reader alerts.</p>'}</section></div><section class="panel"><h3>Live sessions now</h3>${sessionTable()}</section>`}

function adminReaders(){let r=data.readers.find(x=>x.id===adminReaderId)||data.readers[0];adminReaderId=r?.id||'';let taps=data.events.filter(e=>e.readerId===r?.id),hourBins=['07','08','09','10','11','12','13','14'].map(h=>({h,n:taps.filter(e=>new Date(e.timestamp).getHours()===Number(h)).length})),max=Math.max(1,...hourBins.map(x=>x.n));return heading('Readers',`${data.readers.length} configured readers · browser simulation`,`<button class="btn primary" id="addReader">Add reader</button>`)+`<section class="panel"><h3>Reader list</h3><div class="table-scroll"><table><thead><tr><th>Reader</th><th>Room</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.readers.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${esc(x.room)}</td><td>${pill(x.status,x.status==='Online'?'present':'absent')}</td><td><button class="btn outline small" data-view-reader="${esc(x.id)}">View details</button></td></tr>`).join('')}</tbody></table></div></section><div class="reader-detail-head"><div><p class="muted">Readers / ${esc(r?.id||'')}</p><h2>Reader ${esc(r?.id||'')} ${pill(r?.status||'Offline',r?.status==='Online'?'present':'absent')}</h2></div><div class="actions"><button class="btn outline" id="restartReader">Restart reader</button><button class="btn primary" id="notifyReaderICT">Notify ICT</button></div></div><div class="admin-report-bottom"><section class="panel"><h3>Details</h3>${[['Room',r?.room||'—'],['Network','Simulation only · no network connection'],['Firmware',r?.firmware||'Not reported'],['Power','Not connected to physical hardware'],['Key','Not provisioned'],['Added','Configured in the shared register']].map(([a,b])=>`<div class="rowline"><span class="muted">${a}</span><strong>${esc(b)}</strong></div>`).join('')}<div class="actions"><label>Status <select id="readerStatus"><option ${r?.status==='Online'?'selected':''}>Online</option><option ${r?.status==='Offline'?'selected':''}>Offline</option></select></label><button class="btn outline small" id="saveReaderStatus">Save status</button></div></section><section class="panel"><h3>Taps today</h3><p class="muted">${taps.length} recorded tap events for this reader</p><div class="admin-bars reader-bars">${hourBins.map(x=>`<button class="admin-bar-cell" data-reader-hour="${x.h}" title="${x.h}:00 · ${x.n} taps"><strong>${x.n||''}</strong><span class="admin-bar" style="height:${x.n?Math.max(10,x.n/max*100):2}%"></span><small>${x.h}:00</small></button>`).join('')}</div><p id="readerHourInfo" class="muted">Select a bar to inspect the hour.</p></section></div><section class="panel" style="margin-top:18px"><h3>Add a reader</h3><p class="muted">Three steps. A physical reader displays a six-digit pairing code when powered on. This prototype validates a sample code but cannot pair hardware.</p><div class="reader-steps"><div class="reader-step"><b>1. Pick the room</b><select id="pairRoom">${data.rooms.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} · ${esc(x.building)}</option>`).join('')}</select></div><div class="reader-step"><b>2. Enter the pairing code</b><input id="pairCode" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="6-digit code"></div><div class="reader-step"><b>3. Test it</b><p>Simulate a reader test before adding it to the room.</p><span id="pairTestStatus" class="muted">Not tested</span></div></div><div class="actions" style="margin-top:18px"><button class="btn outline" id="pairTest">Test reader</button><button class="btn primary" id="pairContinue">Continue</button></div><div id="readerEditor"></div></section>`}

function adminRooms(){return heading('Rooms',`${data.rooms.length} teaching rooms · ${data.readers.length} readers`,`<button class="btn primary" id="addRoom">+ Add room</button>`)+`<div class="admin-grid"><section class="panel"><div class="table-scroll"><table><thead><tr><th>Room</th><th>Building</th><th>Seats</th><th>Readers</th><th>Sessions</th><th></th></tr></thead><tbody>${data.rooms.map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.building)}</td><td>${r.seats}</td><td>${esc(data.readers.filter(x=>x.room===r.name).map(x=>x.id).join(', ')||'—')}</td><td>${data.sessions.filter(x=>x.room===r.name).length}</td><td><button class="btn outline small" data-edit-room="${i}">Edit room</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h3>Room details</h3><div id="roomEditor">Select Edit room or Add room to manage a teaching space.</div></section></div>`}

function adminCourses(){return heading('Courses','Course assignments and attendance · local sample records',`<div class="header-actions"><button class="btn outline" id="syncCourses">Sync now</button><button class="btn primary" id="addCourse">+ Add course</button></div>`)+`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Course</th><th>Title</th><th>Lecturer</th><th>Students</th><th>Sessions</th><th>Attendance</th><th></th></tr></thead><tbody>${Object.entries(data.courses).map(([m,n])=>{let ss=data.sessions.filter(s=>s.module===m&&s.status==='closed'),ev=ss.reduce((sum,x)=>sum+attendanceFor(x.id).present.size,0),tot=ss.reduce((sum,x)=>sum+attendanceFor(x.id).registered.length,0),rate=tot?Math.round(ev/tot*100):null;return `<tr><td><strong>${esc(m)}</strong></td><td>${esc(courseTitle(m))}</td><td><select data-course="${esc(m)}"><option value="">No lecturer</option>${data.users.filter(u=>u.role==='Lecturer').map(u=>`<option ${u.name===n?'selected':''}>${esc(u.name)}</option>`).join('')}</select></td><td>${people.filter(p=>p.modules.includes(m)).length}</td><td>${ss.length}</td><td>${rate===null?'—':rate+'%'}</td><td>${!n?pill('No lecturer','absent'):rate!==null&&rate<75?pill('Below 75%','pending'):`<button class="btn outline small" data-open-course="${esc(m)}">Open</button>`}</td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="btn primary" id="saveCourses">Save assignments</button></div><div id="courseEditor"></div><p class="muted">Attendance uses completed sessions only. NUST timetable synchronisation is not connected.</p></section>`}

function adminRoles(){let counts=r=>data.users.filter(x=>x.role===r).length;return heading('Roles & access','Who can use the Attendance Desk',`<button class="btn primary" id="addUser">+ Add person</button>`)+`<div class="filter-pills"><button class="btn outline small" data-role-filter="All">All ${data.users.length}</button>${['Admin','Lecturer','Assistant'].map(r=>`<button class="btn outline small" data-role-filter="${r}">${r}s ${counts(r)}</button>`).join('')}</div><div class="admin-grid"><section class="panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Courses</th></tr></thead><tbody>${data.users.map((u,i)=>`<tr data-role-row="${esc(u.role)}"><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><select data-user-role="${i}">${['Admin','Lecturer','Assistant'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${esc(u.course||'—')}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" id="saveRoles">Save roles</button><div id="userEditor"></div></section><section class="panel"><h3>What each role can do</h3>${[['Admin','Rooms, readers, courses, reports, roles and audit log'],['Lecturer','Assigned courses, sessions, register, corrections and reports'],['Assistant','Session management only, no attendance corrections'],['Student','Own taps, attendance and messages']].map(([r,t])=>`<div class="rowline"><strong>${r}</strong><span>${t}</span></div>`).join('')}</section></div>`}

function adminAudit(){let types=['All','Marked by hand','Role changes','Readers','Sessions'],matches=a=>{let t=a.action.toLowerCase();return adminAuditFilter==='All'||(adminAuditFilter==='Marked by hand'&&/correction|manual|undo/.test(t))||(adminAuditFilter==='Role changes'&&/role|staff|user/.test(t))||(adminAuditFilter==='Readers'&&/reader|ict/.test(t))||(adminAuditFilter==='Sessions'&&/session|course/.test(t))},rows=data.audit.slice().reverse().filter(matches);return heading('Audit log','Every manual change kept for the semester · read only',`<button class="btn primary" id="exportAudit">Export CSV</button>`)+`<div class="filter-pills">${types.map(t=>`<button class="btn ${adminAuditFilter===t?'dark':'outline'} small" data-audit-filter="${t}">${t}</button>`).join('')}</div><section class="panel"><div class="table-scroll"><table><thead><tr><th>When</th><th>Who</th><th>What</th><th>Details</th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(fmt(a.timestamp))}</strong></td><td>${esc(a.actor)}</td><td>${pill(a.action,/correction|manual/i.test(a.action)?'purple':/offline/i.test(a.action)?'absent':'present')}</td><td>${esc(a.detail)}</td></tr>`).join('')||'<tr><td colspan="4">No matching changes recorded yet.</td></tr>'}</tbody></table></div></section>`}

function studentHome(){let p=person('MOCK-0187'),mine=data.sessions.filter(x=>p.modules.includes(x.module)),present=mine.filter(x=>attendanceFor(x.id).present.has(p.id)).length,rate=mine.length?Math.round(present/mine.length*100):0;return heading('My Attendance','Your private attendance overview')+`<div class="report-metrics"><div class="metric green">Recorded attendance<strong>${rate}%</strong></div><div class="metric blue">My modules<strong>${p.modules.length}</strong></div><div class="metric yellow">Sessions<strong>${mine.length}</strong></div><div class="metric purple">My queries<strong>${data.queries.filter(q=>q.studentId===p.id).length}</strong></div></div><section class="panel" style="margin-top:18px"><h3>Recent attendance</h3><div class="table-scroll"><table><thead><tr><th>Module</th><th>Session</th><th>Status</th><th>Tap IN</th><th>Tap OUT</th></tr></thead><tbody>${mine.map(x=>{let e=eventsFor(x.id).filter(e=>e.tagId===p.id);return `<tr><td>${esc(x.module)}</td><td>${esc(x.type)} · ${esc(x.room)}</td><td>${pill(statusOf(p.id,x.id))}</td><td>${e.find(t=>t.direction==='IN')?clock(e.find(t=>t.direction==='IN').timestamp):'—'}</td><td>${e.find(t=>t.direction==='OUT')?clock(e.find(t=>t.direction==='OUT').timestamp):'—'}</td></tr>`}).join('')}</tbody></table></div><div class="actions" style="margin-top:20px"><button class="btn primary" data-go="Messages">Report an attendance issue</button><button class="btn outline" data-go="My Modules">My modules</button></div></section>`}

function privacy(){return heading('Privacy','How attendance information should be handled')+`<section class="panel privacy-copy"><h3>What the system records</h3><p>When a student chooses to tap their cuff, the attendance system needs the tag identifier, reader identifier, session and time. A future backend should match the tag to the right student and class.</p><h3>What the system does not need</h3><p>Attendance does not require continuous location tracking, movement history, body temperature or energy harvesting information.</p><h3>Who can see the information</h3><p>Students should only see their own attendance. Lecturers should only access their assigned classes. Administrators should have limited access based on their duties.</p><h3>Correcting a mistake</h3><p>Students can send an attendance query but cannot change the register. Lecturers can make a correction with a reason, their name and the time recorded for review.</p><h3>Before real student data is used</h3><p>NUST must approve the sign-in method, privacy notice, access controls, retention period and process for handling student queries. These safeguards are not enforced by this local browser prototype.</p><div class="note">This prototype uses fictional students and stores its sample records in this browser only. It is not connected to Unity, Render, NUST ITS or physical NFC hardware.</div></section>`}
function settings(){let st=data.settings,lect=role==='lecturer';return heading('Settings',lect?'Your defaults for new sessions and alerts':'Account and preferences')+ (lect?`<div class="settings-grid"><section class="panel"><h3>Session defaults</h3><div class="rowline"><label for="lateSetting">Late after</label><select id="lateSetting">${[5,10,15,20].map(n=>`<option value="${n}" ${st.late===n?'selected':''}>${n} min</option>`).join('')}</select></div><div class="rowline"><span>Open the session</span><select id="openBeforeSetting">${[0,5,10,15].map(n=>`<option value="${n}" ${st.openBefore===n?'selected':''}>${n} min before start</option>`).join('')}</select></div><div class="rowline"><span>Close the session</span><label><input type="checkbox" id="autoCloseSetting" ${st.autoClose?'checked':''}> At the end time</label></div><div class="rowline"><label for="afterCloseSetting">Taps after close</label><select id="afterCloseSetting"><option value="reject" ${st.afterClose!=='review'?'selected':''}>Rejected</option><option value="review" ${st.afterClose==='review'?'selected':''}>Flag for review</option></select></div><div class="rowline"><span>Default room for EPH810S</span><select id="defaultRoomSetting">${data.rooms.map(r=>`<option value="${esc(r.name)}" ${r.name===(st.defaultRoom||'E201')?'selected':''}>${esc(r.name)} · ${esc(r.building)}</option>`).join('')}</select></div></section><section class="panel"><h3>Alerts</h3>${[['alertReader','Reader in my room goes offline'],['alertAbsence','A student reaches 3 absences'],['alertSummary','Daily summary email at 17:00'],['alertAutoOpen','Session opened by itself'],['alertCorrection','Student marked present by another lecturer']].map(([k,l])=>`<label class="rowline"><span>${l}</span><input type="checkbox" data-setting="${k}" ${st[k]?'checked':''}></label>`).join('')}</section><section class="panel"><h3>Export</h3><p>Format <strong>CSV</strong></p><p>Columns <strong>Student no., name, time in, time out, status</strong></p><p>Send to NUST ITS <strong>Every Friday 18:00</strong></p><button class="btn outline" id="exportSettings">Export attendance CSV</button></section><section class="panel account-panel"><h3>Account</h3><p>${esc(roles[role].name)}</p><p>Role: Lecturer</p><p>Courses: ${Object.entries(data.courses).filter(([m,n])=>n===roles[role].name).map(([m])=>m).join(', ')}</p><button class="btn outline" id="signOutSettings">Sign out</button></section></div>`:`<div class="settings-grid"><section class="panel"><h3>My account</h3><div class="rowline"><span>Student</span><strong>${esc(roles[role].name)}</strong></div><div class="rowline"><span>Student number</span><strong>MOCK-0187</strong></div><div class="rowline"><span>Registered modules</span><strong>${esc(person('MOCK-0187').modules.join(', '))}</strong></div><button class="btn outline" id="signOutSettings">Sign out</button></section><section class="panel"><h3>Attendance preferences</h3><p class="muted">Your attendance is read-only. Use Messages to request a review if a record looks incorrect.</p><div class="rowline"><span>Attendance issue enquiries</span><button class="btn outline small" data-go="Messages">Open messages</button></div><div class="rowline"><span>My attendance history</span><button class="btn outline small" data-go="My Attendance">View history</button></div></section></div>`)}

function privacySection(){return `<section class="panel privacy-entry"><div><h3>Privacy and consent</h3><p class="muted">Learn how cuff taps, attendance records and corrections are handled.</p></div><button class="btn outline" id="openPrivacy">View privacy and consent</button></section><div id="privacyModal" class="modal-overlay" hidden></div>`}
function openPrivacyModal(){let m=$('privacyModal');if(!m)return;m.hidden=false;m.innerHTML=`<div class="modal-content privacy-modal" role="dialog" aria-modal="true" aria-labelledby="privacyTitle"><div class="panel-head"><h2 id="privacyTitle">Privacy and consent</h2><button class="btn outline" id="closePrivacy">Close</button></div><h3>How a cuff tap works</h3><p>A student deliberately brings the registered jacket cuff near the NFC reader at the classroom entrance. The reader identifies the tag and associates the tap with the selected class session. Tap IN records arrival and Tap OUT records departure.</p><h3>Information recorded</h3><p>Each accepted tap records the tag identifier, session identifier, reader identifier, direction (IN or OUT) and timestamp. The attendance register uses this information to show participation for that session.</p><h3>Information not collected for attendance</h3><p>The attendance process does not need continuous location tracking, movement history, temperature measurements or energy-harvesting information.</p><h3>Who can access the information</h3><p>Students view their own attendance. Lecturers review their assigned classes and can correct missed taps. Administrators manage authorised system records and access.</p><h3>Corrections and student queries</h3><p>A student can send a message requesting a review but cannot change the register. A lecturer's manual correction includes a reason and is recorded in the audit log.</p><h3>Consent and retention</h3><p>Students should receive a clear privacy notice before using the system. NUST must approve the consent process, retention period and access rules before deployment.</p><div class="actions"><button class="btn primary" id="privacyDone">I understand</button></div></div>`;let close=()=>{m.hidden=true;m.innerHTML=''};m.querySelector('#closePrivacy').onclick=close;m.querySelector('#privacyDone').onclick=close;m.onclick=e=>{if(e.target===m)close()}}

function exportRows(rows,name){let csv=rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=u;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function readerDetails(id){let r=data.readers.find(x=>x.id===id);return heading('Reader '+id,'Reader configuration and activity',`<button class="btn outline" data-go="Readers">Back to readers</button>`)+`<div class="settings-grid"><section class="panel"><h3>Details</h3><div class="rowline"><span>Room</span><strong>${esc(r.room)}</strong></div><div class="rowline"><span>Status</span>${pill(r.status,r.status==='Online'?'present':'absent')}</div><div class="rowline"><span>Taps recorded</span><strong>${data.events.filter(e=>e.readerId===id).length}</strong></div><label>Assign room <select id="readerRoom">${data.rooms.map(x=>`<option ${x.name===r.room?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="btn primary" id="saveReaderRoom">Save reader</button></section><section class="panel"><h3>Taps today</h3>${eventTable(data.events.filter(e=>e.readerId===id))}</section></div>`}
function roomEditor(i){let r=i<0?{name:'',building:'Engineering',seats:40}:data.rooms[i];$('roomEditor').innerHTML=`<form id="roomForm" class="editor"><h3>${i<0?'Add room':'Edit room'}</h3><label>Room <input id="roomName" value="${esc(r.name)}" required></label><label>Building <input id="roomBuilding" value="${esc(r.building)}" required></label><label>Seats <input id="roomSeats" type="number" min="1" value="${r.seats}" required></label><button class="btn primary">Save room</button></form>`;$('roomForm').onsubmit=e=>{e.preventDefault();let updated={name:$('roomName').value.trim(),building:$('roomBuilding').value.trim(),seats:Number($('roomSeats').value)};if(i<0)data.rooms.push(updated);else{let old=data.rooms[i].name;data.rooms[i]=updated;data.readers.forEach(x=>{if(x.room===old)x.room=updated.name});data.sessions.forEach(x=>{if(x.room===old)x.room=updated.name})}audit(i<0?'Room added':'Room updated',updated.name);render()}}
function render(){if(!navigatingHistory){let route=role?role+'/'+page:'';if(route!==lastRoute){history.pushState({role,page},'',role?'#'+role+'/'+encodeURIComponent(page):location.pathname+location.search);lastRoute=route}}if(!role||!roles[role]){login();return}if(!roles[role].nav.includes(page))page=roles[role].nav[0];let views=role==='lecturer'?{Today:today,Sessions:sessions,Register:register,Reports:reports,Messages:messages,Settings:settings}:role==='student'?{'Tap Station':tap,'My Attendance':studentHome,'My Modules':()=>heading('My Modules','Modules linked to this sample student')+`<section class="panel">${person('MOCK-0187').modules.map(m=>`<div class="rowline"><strong>${esc(m)}</strong>${pill('Registered','present')}</div>`).join('')}</section>`,Messages:messages,Settings:settings}:{Overview:adminOverview,Readers:adminReaders,Rooms:adminRooms,Courses:adminCourses,Reports:adminReports,Roles:adminRoles,'Audit log':adminAudit,Settings:settings};shell(views[page]()+ (page==='Settings'?privacySection()+(role==='student'?'':`<section class="panel" style="margin-top:18px"><h3>Attendance data</h3><button class="btn outline" id="reset">Reset attendance records</button></section>`):''));wire()}

let reportModule='EPH810S';
function riskPanel(module){let closed=data.sessions.filter(x=>x.module===module&&x.status==='closed');return people.filter(p=>p.modules.includes(module)).map(p=>{let attended=closed.filter(x=>attendanceFor(x.id).present.has(p.id)).length,rate=closed.length?Math.round(attended/closed.length*100):0;if(rate>=75)return '';let remaining=Math.max(0,Math.ceil((.75*closed.length-attended)/.25));return `<div class="risk-person"><strong>${esc(p.name)}</strong><span class="risk-rate">${rate}%</span><p>${closed.length?`${esc(p.name)} needs ${remaining} more sessions present in a row to reach 75%, if those sessions are held.`:'No completed sessions yet. The 75% calculation will begin after a session closes.'}</p><div class="actions"><button class="btn outline small" data-remind="${p.id}">Send reminder</button><button class="btn outline small" data-support="${p.id}">Refer to student support</button><button class="btn outline small" data-student="${p.id}">View history</button></div></div>`}).join('')||'<p>All registered students are at or above 75%.</p>'}
function checkinChart(s){let ev=eventsFor(s.id).filter(e=>e.direction==='IN'),start=s.time.slice(0,5),[h,m]=start.split(':').map(Number),base=new Date(`${s.date||localDay(new Date())}T${start}:00`),bins=Array.from({length:12},(_,i)=>{let d=new Date(base.getTime()+(i-2)*2*60000);return {time:d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),count:0,start:d.getTime()}});ev.forEach(e=>{let t=new Date(e.timestamp).getTime(),i=bins.findIndex(b=>t>=b.start&&t<b.start+120000);if(i>=0)bins[i].count++});let max=Math.max(1,...bins.map(b=>b.count));return `<div class="checkin-chart">${bins.map(b=>`<div class="checkin-col"><strong>${b.count||''}</strong><div class="checkin-bar" style="height:${b.count?Math.max(8,Math.round(b.count/max*100)):0}%"></div><small>${b.time}</small></div>`).join('')}</div><p class="muted">${ev.length} Tap IN event${ev.length===1?'':'s'} recorded for this session.</p>`}
function closedSummary(s){let a=attendanceFor(s.id),abs=a.registered.filter(p=>!a.present.has(p.id));return `<section class="panel closed-panel"><div class="panel-head"><div><h2>Session closed</h2><p class="muted">${esc(s.module)} · ${esc(s.time)} · Closed ${s.closedAt?clock(s.closedAt):''}</p></div><button class="btn outline" id="exportSettings">Export attendance CSV</button></div><div class="report-metrics"><div class="metric green">Present<strong>${a.present.size} of ${a.registered.length}</strong></div><div class="metric green">Tap IN<strong>${a.ins.size}</strong></div><div class="metric yellow">Tap OUT<strong>${a.outs.size}</strong></div><div class="metric pink">Absent<strong>${abs.length}</strong></div></div><h3>Absent students</h3>${abs.map(p=>`<div class="risk-row"><strong>${esc(p.name)}</strong><span>Absent</span><button class="btn outline small" data-remind="${p.id}">Remind</button></div>`).join('')||'<p>None.</p>'}</section>`}
function studentDetail(id){let p=person(id);if(!p)return;let module=selected().module,ss=data.sessions.filter(x=>x.module===module&&x.status==='closed'),att=ss.filter(x=>attendanceFor(x.id).present.has(id)).length,rate=ss.length?Math.round(att/ss.length*100):0,late=ss.filter(x=>eventsFor(x.id).some(e=>e.tagId===id&&e.direction==='IN'&&new Date(e.timestamp)>new Date(x.date+'T'+x.time.slice(0,5)+':00').getTime()+data.settings.late*60000)).length;let root=document.createElement('div');root.className='modal-overlay';root.id='detailModal';root.innerHTML=`<div class="modal-content detail-content" role="dialog" aria-modal="true"><div class="panel-head"><div><p class="muted">Register / ${esc(module)} / Student</p><h2>${esc(p.name)}</h2><p class="muted">${esc(p.id)} · ${esc(module)}</p></div><button class="btn outline" id="closeDetail">Close</button></div><div class="report-metrics"><div class="metric pink">Attendance this semester<strong>${rate}%</strong></div><div class="metric green">Sessions attended<strong>${att} of ${ss.length}</strong></div><div class="metric yellow">Late arrivals<strong>${late}</strong></div><div class="metric purple">Fixed by hand<strong>${data.corrections.filter(c=>c.tagId===id&&ss.some(x=>x.id===c.sessionId)).length}</strong></div></div><section class="panel"><h3>Last sessions</h3><div class="history-chips">${ss.slice(-10).map(x=>{let st=statusOf(id,x.id),c=st==='Absent'?'pink':st==='Fixed by hand'?'purple':'green';return `<div class="history-chip ${c}"><strong>${st==='Absent'?'A':st==='Fixed by hand'?'M':'P'}</strong><small>${esc(x.date||'')}</small></div>`}).join('')||'<p>No closed sessions yet.</p>'}</div></section><div class="detail-bottom"><section class="panel"><h3>Tap history</h3>${eventTable(data.events.filter(e=>e.tagId===id&&data.sessions.some(x=>x.id===e.sessionId&&x.module===module)).slice().reverse())}</section><section class="panel pink"><h3>Below the 75% rule</h3>${riskPanel(module)}</section></div><button class="btn primary" id="detailCorrect">Mark present by hand</button></div>`;document.body.append(root);root.onclick=e=>{if(e.target===root)root.remove()};root.querySelector('#closeDetail').onclick=()=>root.remove();root.querySelector('#detailCorrect').onclick=()=>{root.remove();correctionForm(id)};root.querySelectorAll('[data-remind],[data-support]').forEach(b=>b.onclick=()=>sendReminder(b.dataset.remind||b.dataset.support,b.hasAttribute('data-support')))}
function sendReminder(id,support=false){let p=person(id),sel=selected();if(!p||!sel)return;let ss=data.sessions.filter(x=>x.module===sel.module&&x.status==='closed'),att=ss.filter(x=>attendanceFor(x.id).present.has(id)).length,rate=ss.length?Math.round(att/ss.length*100):0;let kind=support?'support':'reminder',day=localDay(new Date());if(data.queries.some(q=>q.studentId===id&&q.kind===kind&&q.sentDay===day&&q.module===sel.module)){notice='A '+(support?'referral':'reminder')+' was already created for this student today.';render();return}let body=support?`Student support referral requested for ${sel.module}. Current attendance: ${rate}%.`:`Attendance reminder for ${sel.module}: your recorded attendance is ${rate}%. Please review your sessions and contact your lecturer through Messages if a record is incorrect.`;data.queries.push({id:'Q-'+Date.now(),studentId:id,sessionId:sel.id,module:sel.module,kind,sentDay:day,text:body,status:'Sent',timestamp:new Date().toISOString(),reply:'',from:'Lecturer'});audit(support?'Student support referral':'Attendance reminder',p.name+' · '+sel.module+' · '+rate+'%');notice=(support?'Support referral':'In-app reminder')+' created for '+p.name+'.';render()}
