// API connection settings are optional. Local demo remains fully functional when disabled.
const baseSettings=settings;
settings=function(){
 const integration=window.KinectoIntegration;
 const cfg=integration?.getStatus().config||{url:'',interval:5000,enabled:false};
 const panel=(role==='lecturer'||role==='admin')?`<section class="panel" style="margin-top:18px"><h3>Unity attendance integration</h3><p class="muted">Local Tap Station simulation stays available. For remote events, enter a backend GET URL that returns validated attendance events. This browser does not host an endpoint.</p><div class="field"><label for="apiEventsUrl">Validated events feed URL (HTTPS)</label><input id="apiEventsUrl" type="url" placeholder="https://your-backend.example/api/attendance/events" value="${esc(cfg.url)}"></div><div class="rowline"><label for="apiEnabled">Fetch events from API</label><input id="apiEnabled" type="checkbox" ${cfg.enabled?'checked':''}></div><div class="actions"><button class="btn primary" id="apiSave">Save connection</button><button class="btn outline" id="apiRefresh">Fetch now</button></div><p id="apiStatus" class="muted" aria-live="polite">${esc(integration?.statusText()||'Integration module loading...')}</p><p class="muted">Use a backend you trust. Do not paste a private API key here. This is a prototype without secure sign-in.</p></section>`:'';
 return baseSettings()+panel;
};
const baseWireWithSettings=wire;
wire=function(){baseWireWithSettings();
 const integration=window.KinectoIntegration;
 if($('apiSave'))$('apiSave').onclick=()=>{
  const url=$('apiEventsUrl').value.trim(),enabled=$('apiEnabled').checked;
  if(enabled&&!/^https:\/\//i.test(url)&&!/^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?\//i.test(url)){notice='Use an HTTPS events URL, or HTTP localhost for development.';render();return}
  integration.configure({url,enabled});notice=enabled?'API polling enabled. Local demo remains available.':'Local demo mode enabled.';render();
 };
 if($('apiRefresh'))$('apiRefresh').onclick=()=>integration.poll();
};

window.addEventListener('popstate',e=>{navigatingHistory=true;let state=e.state;if(state&&state.role&&roles[state.role]){role=state.role;sessionStorage.setItem(AUTH,role);page=roles[role].nav.includes(state.page)?state.page:roles[role].nav[0]}else{let match=location.hash.match(/^#(lecturer|student|admin)\/(.*)$/);if(match){role=match[1];sessionStorage.setItem(AUTH,role);let requested=decodeURIComponent(match[2]);page=roles[role].nav.includes(requested)?requested:roles[role].nav[0]}else{role='';sessionStorage.removeItem(AUTH)}}lastRoute=role?role+'/'+page:'';notice='';render();navigatingHistory=false});
const initialRoute=location.hash.match(/^#(lecturer|student|admin)\/(.*)$/);if(initialRoute&&sessionStorage.getItem(AUTH)===initialRoute[1]){role=initialRoute[1];let requested=decodeURIComponent(initialRoute[2]);page=roles[role].nav.includes(requested)?requested:roles[role].nav[0]}else if(role&&roles[role])page=roles[role].nav[0];history.replaceState({role,page},'',role?'#'+role+'/'+encodeURIComponent(page):location.pathname+location.search);lastRoute=role?role+'/'+page:'';
render();
